import{_ as s,C as o,o as n,c as i,j as t,a,E as h,ah as d}from"./chunks/framework.Be4_4mPW.js";const k=JSON.parse('{"title":"Phase 1: one interface, two backends, one judge","description":"","frontmatter":{"title":"Phase 1: one interface, two backends, one judge","date":"2026-10-24T00:00:00.000Z","phase":1,"status":"gate"},"headers":[],"relativePath":"blog/phase-1-contracts-and-transports.md","filePath":"blog/phase-1-contracts-and-transports.md"}'),l={name:"blog/phase-1-contracts-and-transports.md"};function c(p,e,m,u,b,f){const r=o("Mermaid");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"phase-1-one-interface-two-backends-one-judge",tabindex:"-1"},[a("Phase 1: one interface, two backends, one judge "),t("a",{class:"header-anchor",href:"#phase-1-one-interface-two-backends-one-judge","aria-label":'Permalink to "Phase 1: one interface, two backends, one judge"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Phase 1 built everything between the app and the server. There is still no player screen. What exists now is the plumbing that every screen in Phase 2 will use, and a way to prove that the demo backend tells the truth.",-1)),e[2]||(e[2]=t("h2",{id:"the-shape-of-it",tabindex:"-1"},[a("The shape of it "),t("a",{class:"header-anchor",href:"#the-shape-of-it","aria-label":'Permalink to "The shape of it"'},"​")],-1)),h(r,{code:"flowchart%20TB%0A%20%20%20%20hooks%5B%22React%20hooks%22%5D%20--%3E%20store%5B%22Session%20store%20and%20domain%20layer%22%5D%0A%20%20%20%20store%20--%3E%20iface%5B%22Transport%20interface%22%5D%0A%20%20%20%20iface%20--%3E%20real%5B%22Real%20transport%3A%20StanzaJS%20and%20an%20ejabberd%20adapter%22%5D%0A%20%20%20%20iface%20--%3E%20mock%5B%22Mock%20transport%22%5D%0A%20%20%20%20mock%20--%3E%20host%5B%22Mock%20host%3A%20shared%20worker%20or%20leader%20tab%2C%20saved%20in%20the%20browser%22%5D%0A%20%20%20%20host%20--%3E%20server%5B%22Mock%20server%22%5D%0A%20%20%20%20suite%5B%22Contract%20tests%22%5D%20-.%20%22run%20against%22%20.-%3E%20real%0A%20%20%20%20suite%20-.%20%22run%20against%22%20.-%3E%20mock%0A"}),e[3]||(e[3]=d('<ul><li><strong>The transport interface.</strong> One TypeScript interface covers logging in, chat rooms, message history, the documents that describe the game, and server administration. Every operation returns a result rather than throwing, so a refusal from the server is ordinary data, not a crash.</li><li><strong>The real transport.</strong> It talks to ejabberd, the XMPP server WRX1 runs on, and keeps everything specific to that server in one adapter.</li><li><strong>The mock.</strong> A small XMPP-like server written in TypeScript runs in the browser. One copy is shared by every tab of a deployment, so two windows can act as two players. It is saved in the browser, and each deployment of the site keeps its own copy.</li><li><strong>The domain layer.</strong> One store per player pane turns raw server traffic into validated game documents and ordered, de-duplicated chat timelines. Thin React hooks expose it to the UI.</li></ul><h2 id="why-the-mock-can-be-trusted" tabindex="-1">Why the mock can be trusted <a class="header-anchor" href="#why-the-mock-can-be-trusted" aria-label="Permalink to &quot;Why the mock can be trusted&quot;">​</a></h2><p>A demo backend that behaves differently from the real server would mislead every reviewer who used it. So the mock is not tested on its own terms. One suite of contract tests runs against both a real ejabberd server in CI and the mock, and the build fails if they disagree. The mock implements only what those tests cover, and any behaviour it needed beyond them is listed as uncovered.</p><p>The tests earned their keep immediately. They showed that the server will not let one author overwrite another author&#39;s document. That would have stopped umpires from editing objectives written by the admin, so objectives are now kept as one version per author, with the newest shown. The fix landed before any screen was built on the old assumption.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>Only Chromium is tested so far. Firefox and Safari come in Phase 3.</li><li>The mock saves the whole game in one browser record. That is fine for demos, but very long games will make each save slower.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Phase 2 builds the screens: the admin&#39;s game editor and publishing, the player&#39;s welcome page, login and dockable chat workspace, themes, and the multi-client view for demos. It runs in three lanes in parallel.</p>',8))])}const g=s(l,[["render",c]]);export{k as __pageData,g as default};
